export function rotateCipher(text, shift) {
    const amount = ((shift % 26) + 26) % 26;
    return [...text].map(c => {
        const n = c.charCodeAt(0), base = n >= 65 && n <= 90 ? 65 : n >= 97 && n <= 122 ? 97 : null;
        return base === null ? c : String.fromCharCode(base + (n - base + amount) % 26);
    }).join('');
}
